51: namespace RDKit {
52: namespace Utils {
53: namespace detail {
54: // Implementation of LocaleSwitcher
55: //  The locale switcher has state to indicate how many times
56: //   it has been used (in a thread if thread safe RDKIT)
57: 
58: const static int CurrentState = 0;  // return current state
59: const static int SwitchLocale = 1;  // indicate we are now switched to "C"
60: const static int ResetLocale = -1;  // return to previous locale (not "C")
61: 
62: // Returns how many LocaleSwitches we have gone down.
63: //  Such as
64: //    void foo() { LocaleSwitcher switch; }
65: //    void bar() { LocaleSwitcher switch; foo(); }
66: //
67: //  Implementations are free to not switch the locale if the locale
68: //   is already in "C", but this is implementation defined.
69: //  When Recurse(CurrentState) == 0 we are in the "global" locale,
70: //   or at least at the top locale that isn't "C".
71: //
72: static int recurseLocale(int state) {
73: #ifdef RDK_BUILD_THREADSAFE_SSS
74:   static thread_local int recursion = 0;
75: #else
76:   static int recursion = 0;
77: #endif
78:   if (state == SwitchLocale) {
79:     ++recursion;
80:   } else if (state == ResetLocale) {
81:     --recursion;
82:   }
83:   return recursion;
84: }
85: 
86: // allows an RAII-like approach to ensuring the locale is temporarily "C"
87: // instead of whatever we started in.
88: class LocaleSwitcherImpl {
89:  public:
90: #ifdef _WIN32
91: 
92:   LocaleSwitcherImpl() {
93:     if (!recurseLocale(CurrentState)) {
94: #ifdef RDK_BUILD_THREADSAFE_SSS
95:       _configthreadlocale(_ENABLE_PER_THREAD_LOCALE);
96:       old_locale = ::setlocale(LC_ALL, nullptr);
97:       ::setlocale(LC_ALL, "C");  // thread safe on windows
98: #else
99:       old_locale = std::setlocale(LC_ALL, nullptr);
100:       std::setlocale(LC_ALL, "C");
101: #endif  // RDK_BUILD_THREADSAFE_SSS
102:       recurseLocale(SwitchLocale);
103:       switched = true;
104:     }
105:   }
106:   ~LocaleSwitcherImpl() {
107:     if (switched) {
108: #ifdef RDK_BUILD_THREADSAFE_SSS
109:       ::setlocale(LC_ALL, old_locale.c_str());
110: #else
111:       // back to last (global?) locale
112:       std::setlocale(LC_ALL, old_locale.c_str());
113: #endif  // RDK_BUILD_THREADSAFE_SSS
114:       recurseLocale(ResetLocale);
115:     }
116:   }
117: 
118:  public:
119:   bool switched = false;
120:   std::string old_locale;
121: #else  // _WIN32
122:   LocaleSwitcherImpl() {
123:     // set locale for this thread
124: 
125:     if (!recurseLocale(CurrentState)) {
126:       auto loc = newlocale(LC_ALL_MASK, "C", (locale_t) nullptr);
127:       old_loc = uselocale(loc);
128:       recurseLocale(SwitchLocale);
129:       switched = true;
130:     }
131:   }
132:   ~LocaleSwitcherImpl() {
133:     if (switched) {
134:       auto loc = uselocale(old_loc);
135:       freelocale(loc);
136:       recurseLocale(ResetLocale);
137:     }
138:   }
139: 
140:  private:
141:   bool switched = false;
142:   locale_t old_loc;  // locale we came from
143: 
144: #endif  // _WIN32
145: };
146: }  // namespace detail
147: 
148: // allows an RAII-like approach to ensuring the locale is temporarily "C"
149: // instead of whatever we started in.
150: 
151: LocaleSwitcher::LocaleSwitcher() : impl(new detail::LocaleSwitcherImpl) {}
152: LocaleSwitcher::~LocaleSwitcher() { delete impl; }
153: }  // namespace Utils
154: }  // namespace RDKit

