269: double bitstringTanimotoSimilarity(int length, uint8 *bstr1, uint8 *bstr2) {
270:   double sim;
271: 
272:   int union_popcount = 0;
273:   int intersect_popcount = 0;
274: 
275:   uint8 *bstr1_end = bstr1 + length;
276: 
277: #ifdef RDK_OPTIMIZE_POPCNT
278:   int ilength = length / sizeof(POPCNT_TYPE);
279: 
280:   POPCNT_TYPE *ibstr1 = (POPCNT_TYPE *)bstr1;
281:   POPCNT_TYPE *ibstr2 = (POPCNT_TYPE *)bstr2;
282:   POPCNT_TYPE *ibstr1_end = ibstr1 + ilength;
283:   POPCNT_TYPE *ibstr1_end4 = ibstr1_end - (ilength % 4);
284: 
285:   POPCNT_TYPE ib1, ib2;
286:   while (ibstr1 < ibstr1_end4) {
287:     ib1 = *ibstr1++;
288:     ib2 = *ibstr2++;
289:     union_popcount += POPCNT(ib1 | ib2);
290:     intersect_popcount += POPCNT(ib1 & ib2);
291:     ib1 = *ibstr1++;
292:     ib2 = *ibstr2++;
293:     union_popcount += POPCNT(ib1 | ib2);
294:     intersect_popcount += POPCNT(ib1 & ib2);
295:     ib1 = *ibstr1++;
296:     ib2 = *ibstr2++;
297:     union_popcount += POPCNT(ib1 | ib2);
298:     intersect_popcount += POPCNT(ib1 & ib2);
299:     ib1 = *ibstr1++;
300:     ib2 = *ibstr2++;
301:     union_popcount += POPCNT(ib1 | ib2);
302:     intersect_popcount += POPCNT(ib1 & ib2);
303:   }
304: 
305:   while (ibstr1 < ibstr1_end) {
306:     ib1 = *ibstr1++;
307:     ib2 = *ibstr2++;
308:     union_popcount += POPCNT(ib1 | ib2);
309:     intersect_popcount += POPCNT(ib1 & ib2);
310:   }
311: 
312:   bstr1 = (uint8 *)ibstr1;
313:   bstr2 = (uint8 *)ibstr2;
314: #endif
315: 
316:   while (bstr1 < bstr1_end) {
317:     uint8 b1 = *bstr1++;
318:     uint8 b2 = *bstr2++;
319:     union_popcount += number_of_ones[b1 | b2];
320:     intersect_popcount += number_of_ones[b1 & b2];
321:   }
322: 
323:   if (union_popcount != 0) {
324:     sim = ((double)intersect_popcount) / union_popcount;
325:   } else {
326:     sim = 1.0;
327:   }
328: 
329:   return sim;
