411: void bitstringSimpleSubset(int length, uint8 *bstr, int sub_weight,
412:                            uint8 *sub_bstr) {
413:   /*
414:   ** a simple implementation. just pick the first sub_weight 1s from bstr
415:   ** and set them in sub_bstr
416:   */
417: 
418:   uint8 *bstr_end = bstr + length;
419: 
420:   int i;
421:   int bitcount = 0;
422:   uint8 bit, byte;
423: 
424:   while (bitcount < sub_weight && bstr < bstr_end) {
425:     byte = *bstr++;
426:     for (i = 0, bit = 0x01; bitcount < sub_weight && i < 8; ++i, bit <<= 1) {
427:       if (byte & bit) {
428:         ++bitcount;
429:         *sub_bstr |= bit;
430:       }
431:     }
432:     ++sub_bstr;
433:   }
434: }
