436: void bitstringRandomSubset(int length, int weight, uint8 *bstr, int sub_weight,
437:                            uint8 *sub_bstr) {
438:   int i, j;
439:   int bitindex, bitcount, *bits;
440:   uint8 byte;
441: 
442:   Assert(sub_weight <= weight);
443: 
444:   /* fill an array with the indices of the 1s in bstr */
445:   bits = palloc(weight * sizeof(int));
446: 
447:   for (bitcount = 0, i = 0; i < length; ++i) {
448:     byte = bstr[i];
449:     for (j = 0; j < 8; ++j) {
450:       if (byte & 0x01) {
451:         Assert(bitcount < weight);
452:         bitindex = 8 * i + j;
453:         bits[bitcount++] = bitindex;
454:       }
455:       byte >>= 1;
456:     }
457:   }
458: 
459:   /* move a random subset of bit indices to the front */
460:   for (bitcount = 0; bitcount < sub_weight; ++bitcount) {
461:     /* pick a random index in [bitcount, weight - 1] */
462:     double r = ((double)rand()) / RAND_MAX * (weight - 1 - bitcount);
463:     i = bitcount + (int)(r + .5);
464:     /* swap the values (move the selected entry from i to bitcount) */
465:     bitindex = bits[i];
466:     bits[i] = bits[bitcount];
467:     bits[bitcount] = bitindex;
468:   }
469: 
470:   /* set the selected bits in the output sub_bstr */
471:   for (bitcount = 0; bitcount < sub_weight; ++bitcount) {
472:     bitindex = bits[bitcount];
473:     sub_bstr[bitindex / 8] |= (0x01 << bitindex % 8);
474:   }
475: 
476:   /* deallocate the array of bit indices */
477:   pfree(bits);
478: }
