480: int bitstringGrayCmp(int length, uint8 *bstr1, uint8 *bstr2) {
481:   /*
482:    * Compare two bistrings according to their ordering in a
483:    * Binary Reflected Gray Code
484:    *
485:    * Which digit represents a higher value, 0 or 1 ?
486:    *
487:    * 000
488:    * 001
489:    * 011
490:    * 010
491:    * 110
492:    * 111
493:    * 101
494:    * 100
495:    *
496:    * In contrast to the usual representation of binary numbers,
497:    * the code is not just positional.
498:    * 
499:    * When we start from the leftmost position, 1 > 0. In moving
500:    * to right, every time a pair of 1s is found, it means the
501:    * remaining parts of the codes resulted from a reflection, and
502:    * the digit with the highest value changes from 1 to 0 and
503:    * viceversa.
504:    */
505: 
506:   uint8 higher = 1;
507: 
508:   const uint8 *bstr1_end = bstr1 + length;
509: 
510:   while (bstr1 < bstr1_end) {
511:     const uint8 bytea = *bstr1++;
512:     const uint8 byteb = *bstr2++;
513:     if (bytea == byteb) {
514:       /* if the number of 1s is odd, higher is flipped */
515:       higher ^= (1 & number_of_ones[bytea]);
516:     }
517:     else {
518:       uint8 mask = 0x80;
519:       while (mask) {
520:         uint8 bita = (bytea & mask) ? 1 : 0;
521:         uint8 bitb = (byteb & mask) ? 1 : 0;
522:         if (bita != bitb) {
523:           return (bita == higher) ? 1 : -1;
524:         }
525:         else {
526:           /* flip higher if bita is 1 */
527:           higher ^= bita;
528:         }
529:         mask >>= 1;
530:       }
531:       Assert(!"It should never get here if bytea != byteb");
532:     }
533:   }
534: 
535:   /* same bfp value */
536:   return 0;
537: }

