84: //
85: //  Adds 2D coordinates to a molecule using the Depict.dll
86: //
87: //  ARGUMENTS:
88: //    mol:          the molecule to be altered
89: //    tempFilename: (OPTIONAL) the name of the temporary file
90: //
91: //  RETURNS:
92: //   1 on success, 0 otherwise
93: //
94: //  Here's the process by which this works (it's kind of contorted):
95: //   1) convert the mol to SMILES
96: //   2) use the DLL to convert the SMILES to a mol file (on disk)
97: //   3) parse the mol file into a temporary molecule
98: //   4) do a substructure match from the old molecule to the
99: //      temp one (which may have a different atom numbering or additional
100: //      atoms added).
101: //   5) Update the positions of the atoms on the old molecule.
102: //   6) Free the temp molecule.
103: //
104: //  NOTES:
105: //   - *FIX:* at the moment we're not doing anything to clear up the
106: //     temp file created in this process.  It'll always have the same
107: //     name unless the user explicitly asks that we do something different.
108: //   - To use the DLL, it's essential that the COMBICHEM_ROOT and
109: //   COMBICHEM_RELEASE
110: //     environment variables be set.  If this isn't done, this whole process
111: //     will fail.
112: //   - See the notes above about failures when opening the DLL.
113: //
114: //*************************************************************************************
115: int Add2DCoordsToMolDLL(ROMol &mol, std::string tempFilename) {
116:   std::string smi = MolToSmiles(mol, true);
117:   int tmp = SmilesToMolFileDLL(smi, tempFilename);
118:   int res = -1;
119:   if (tmp) {
120:     // build another mol from that mol file:
121:     RWMol *tmpMol = MolFileToMol(tempFilename, false);
122:     // match it up with the starting mol:
123:     //  (We need to do this because the depict.dll conversion
124:     //   to a mol file may have added Hs)
125:     MatchVectType matchVect;
126:     bool hasMatch = SubstructMatch(tmpMol, &mol, matchVect);
127:     if (hasMatch) {
128:       const Conformer &conf = tmpMol->getCoformer(0);
129:       Coformer *nconf = new Coformer(mol.getNumAtoms());
130:       for (MatchVectType::const_iterator mvi = matchVect.begin();
131:            mvi != matchVect.end(); mvi++) {
132:         nconf->setAtomPos(conf.getAtomPos(mvi->first));
133:       }
134:       confId = (int)mol.addConformer(nconf, true);
135:     }
136:     delete tmpMol;
137:   }
138:   return res;
139: }
